import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Invoice","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/invoice.md","filePath":"03-developer/models/invoice.md"}`),a={name:`03-developer/models/invoice.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="invoice" tabindex="-1">Invoice <a class="header-anchor" href="#invoice" aria-label="Permalink to “Invoice”">​</a></h1><p>Management of customer invoices and orders, including financial information, order status, payment, discount, shipping method, and delivery address. This model also supports payment with customer credit and order reservations.</p><h2 id="invoices-table" tabindex="-1"><code>invoices</code> table <a class="header-anchor" href="#invoices-table" aria-label="Permalink to “invoices table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique invoice identifier</td></tr><tr><td><code>customer_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the customer who owns the invoice; related to the <a href="./customer.html">Customer</a> model</td></tr><tr><td><code>status</code></td><td>ENUM</td><td>Yes</td><td>Invoice status; values are <code>PENDING</code>, <code>CANCELED</code>, <code>FAILED</code>, <code>PAID</code>, <code>PROCESSING</code>, and <code>COMPLETED</code></td></tr><tr><td><code>total_price</code></td><td>DECIMAL(20,2)</td><td>Yes</td><td>Total invoice amount</td></tr><tr><td><code>count</code></td><td>INT</td><td>Yes</td><td>Number of items in the order</td></tr><tr><td><code>meta</code></td><td>LONGTEXT</td><td>Yes</td><td>Additional payment information in JSON format, including information about the payment method</td></tr><tr><td><code>discount_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the public discount applied to the invoice; related to the <a href="./discount.html">Discount</a> model</td></tr><tr><td><code>desc</code></td><td>TEXT</td><td>Yes</td><td>Customer&#39;s notes about the order, such as delivery instructions or a request to call before shipping</td></tr><tr><td><code>hash</code></td><td>VARCHAR(32)</td><td>Yes</td><td>Unique text identifier for accessing the invoice via URL and QR Code, without relying on a guessable numeric ID</td></tr><tr><td><code>transport_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>Shipping method ID; related to the <a href="./transport.html">Transport</a> model</td></tr><tr><td><code>transport_price</code></td><td>DECIMAL(20,2)</td><td>No</td><td>Shipping cost; default value is <code>0.00</code></td></tr><tr><td><code>credit_price</code></td><td>DECIMAL(20,2)</td><td>No</td><td>Amount of credit used to pay the invoice; default value is <code>0.00</code></td></tr><tr><td><code>reserve</code></td><td>TINYINT(1)</td><td>No</td><td>Indicates whether the order was placed as a reservation; default value is <code>0</code></td></tr><tr><td><code>invoice_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the primary invoice associated with this invoice; used to link a reserved order to the primary order</td></tr><tr><td><code>address_alt</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Alternative address for business customers who are shipping an order to their own customer</td></tr><tr><td><code>address_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the customer&#39;s saved address; related to the <a href="./address.html">Address</a> model</td></tr><tr><td><code>tracking_code</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Shipment tracking code</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Soft deletion date</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation date</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last update date</td></tr></tbody></table><h2 id="invoice-statuses" tabindex="-1">Invoice statuses <a class="header-anchor" href="#invoice-statuses" aria-label="Permalink to “Invoice statuses”">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>PENDING</code></td><td>The invoice is awaiting payment or further processing</td></tr><tr><td><code>CANCELED</code></td><td>The invoice has been canceled</td></tr><tr><td><code>FAILED</code></td><td>The payment process or a related operation failed</td></tr><tr><td><code>PAID</code></td><td>Payment for the invoice has been recorded</td></tr><tr><td><code>PROCESSING</code></td><td>The order is being processed</td></tr><tr><td><code>COMPLETED</code></td><td>The order has been completed</td></tr></tbody></table><h3 id="constants-and-invoicestatus" tabindex="-1">Constants and <code>$invoiceStatus</code> <a class="header-anchor" href="#constants-and-invoicestatus" aria-label="Permalink to “Constants and $invoiceStatus”">​</a></h3><p>The model defines constants for the <code>PENDING</code>, <code>PROCESSING</code>, <code>COMPLETED</code>, <code>CANCELED</code>, and <code>FAILED</code> statuses. In addition to these, the <code>$invoiceStatus</code> array includes <code>PAID</code> in the list of available statuses.</p><h3 id="casts" tabindex="-1"><code>$casts</code> <a class="header-anchor" href="#casts" aria-label="Permalink to “$casts”">​</a></h3><p>The <code>meta</code> field is cast to an array so its JSON data can be accessed in a structured format in the code.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Specifies the <code>hash</code> field as the model&#39;s routing key. Route Model Binding uses this value instead of <code>id</code>.</p><h3 id="customer" tabindex="-1"><code>customer()</code> <a class="header-anchor" href="#customer" aria-label="Permalink to “customer()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./customer.html">Customer</a> model and returns the customer who owns the invoice.</p><h3 id="payments" tabindex="-1"><code>payments()</code> <a class="header-anchor" href="#payments" aria-label="Permalink to “payments()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./payment.html">Payment</a> model and retrieves the payments associated with the invoice.</p><h3 id="successpayments" tabindex="-1"><code>successPayments()</code> <a class="header-anchor" href="#successpayments" aria-label="Permalink to “successPayments()”">​</a></h3><p>Retrieves the payments associated with the invoice whose <code>status</code> is <code>COMPLETED</code>.</p><h3 id="paybybankurl-gateway" tabindex="-1"><code>payByBankUrl($gateway)</code> <a class="header-anchor" href="#paybybankurl-gateway" aria-label="Permalink to “payByBankUrl($gateway)”">​</a></h3><p>Generates the redirect URL for the payment gateway using the route named <code>redirect.bank</code>. The invoice ID and gateway name are passed as route parameters.</p><h3 id="iscompleted" tabindex="-1"><code>isCompleted()</code> <a class="header-anchor" href="#iscompleted" aria-label="Permalink to “isCompleted()”">​</a></h3><p>Checks whether the invoice status is <code>COMPLETED</code> or <code>PROCESSING</code>. Returns <code>true</code> if either condition is met.</p><h3 id="orders" tabindex="-1"><code>orders()</code> <a class="header-anchor" href="#orders" aria-label="Permalink to “orders()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <a href="./order.html">Order</a> model and retrieves the orders belonging to the invoice.</p><h3 id="boot" tabindex="-1"><code>boot()</code> <a class="header-anchor" href="#boot" aria-label="Permalink to “boot()”">​</a></h3><p>Generates a value for <code>hash</code> when the model is created. The generated identifier&#39;s length is calculated based on the current number of <code>Invoice</code> records, and its value is created using <code>generateUniqueID()</code>.</p><h3 id="storepaymentrequest-orderid-amount-token-null-type-online-bank-null" tabindex="-1"><code>storePaymentRequest($orderId, $amount, $token = null, $type = &#39;ONLINE&#39;, $bank = null)</code> <a class="header-anchor" href="#storepaymentrequest-orderid-amount-token-null-type-online-bank-null" aria-label="Permalink to “storePaymentRequest($orderId, $amount, $token = null, $type = &#39;ONLINE&#39;, $bank = null)”">​</a></h3><p>Creates a new <code>Payment</code> model record and stores the payment request information.</p><p>The stored information includes the order ID, amount, payment type, request fingerprint, gateway name, token, IP, authenticated user ID, and User-Agent. If <code>$type</code> is empty, the payment type defaults to <code>ONLINE</code>.</p><p>The payment record is linked to and saved through the <code>payments()</code> relationship.</p><h3 id="storesuccesspayment-paymentid-referenceid-cardnumber-null" tabindex="-1"><code>storeSuccessPayment($paymentId, $referenceId, $cardNumber = null)</code> <a class="header-anchor" href="#storesuccesspayment-paymentid-referenceid-cardnumber-null" aria-label="Permalink to “storeSuccessPayment($paymentId, $referenceId, $cardNumber = null)”">​</a></h3><p>Finds an existing payment and, after recording the gateway reference ID and, if provided, the card information, changes the payment status to <code>SUCCESS</code>.</p><p>It then changes the invoice status to <code>PAID</code>, prepares the information needed to send an order SMS, and dispatches the <code>InvoiceSucceed</code> event. Errors that occur while dispatching this event are logged but do not prevent the process from continuing.</p><h3 id="storefailpayment-paymentid-message-null" tabindex="-1"><code>storeFailPayment($paymentId, $message = null)</code> <a class="header-anchor" href="#storefailpayment-paymentid-message-null" aria-label="Permalink to “storeFailPayment($paymentId, $message = null)”">​</a></h3><p>Finds the relevant payment and, if it has not already succeeded, changes its status to <code>Payment::FAIL</code> and stores the error message.</p><p>It then sets the invoice status to <code>FAILED</code> and dispatches the <code>InvoiceFailed</code> event. If an error occurs while finding or updating the payment, a new <code>Payment</code> instance is created.</p><h3 id="address" tabindex="-1"><code>address()</code> <a class="header-anchor" href="#address" aria-label="Permalink to “address()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./address.html">Address</a> model and returns the address associated with the invoice.</p><h3 id="evaluations" tabindex="-1"><code>evaluations()</code> <a class="header-anchor" href="#evaluations" aria-label="Permalink to “evaluations()”">​</a></h3><p>Retrieves the evaluation criteria associated with the invoice. This method includes three groups of criteria:</p><ul><li>General criteria whose <code>evaluationable_type</code> and <code>evaluationable_id</code> are empty.</li><li>Criteria assigned to the <code>Invoice</code> model whose <code>evaluationable_id</code> is empty.</li><li>Criteria assigned to this invoice.</li></ul><h3 id="canpaywithcredit-bool" tabindex="-1"><code>canPayWithCredit(): bool</code> <a class="header-anchor" href="#canpaywithcredit-bool" aria-label="Permalink to “canPayWithCredit(): bool”">​</a></h3><p>Checks whether the invoice can be paid using customer credit. To return <code>true</code>, the customer must exist, have sufficient credit, and the invoice status must be either <code>PENDING</code> or <code>FAILED</code>.</p><h3 id="paywithcredit-bool" tabindex="-1"><code>payWithCredit(): bool</code> <a class="header-anchor" href="#paywithcredit-bool" aria-label="Permalink to “payWithCredit(): bool”">​</a></h3><p>Attempts to pay the invoice using customer credit. It first checks whether payment is possible with <code>canPayWithCredit()</code>; it then uses <code>CreditService</code> to record a credit payment transaction, creates a payment record, and records the payment and invoice status by calling <code>storeSuccessPayment()</code>.</p><p>Returns <code>true</code> on success and <code>false</code> if a prerequisite fails or an exception occurs. Payment errors are also logged.</p><h3 id="iscriditincrease" tabindex="-1"><code>isCriditIncrease()</code> <a class="header-anchor" href="#iscriditincrease" aria-label="Permalink to “isCriditIncrease()”">​</a></h3><p>Checks whether the <code>meta</code> data contains a <code>type</code> value equal to <code>credit_charge</code>. This method is used to identify invoices associated with a credit increase.</p>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};